
CREATE TABLE IF NOT EXISTS public.doctors (
  id bigint PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
  name text NOT NULL,
  designation text,
  hospital text,
  image_url text,
  profile_url text,
  social_links jsonb,
  created_at timestamp with time zone default timezone('utc'::text, now()) not null
);

-- Enable Row Level Security
ALTER TABLE public.doctors ENABLE ROW LEVEL SECURITY;

-- Create policy to allow public read access
CREATE POLICY "Allow public read access on doctors"
  ON public.doctors FOR SELECT
  USING (true);

-- Insert data

-- Update the identity sequence to the max id so that future inserts without id work correctly
SELECT setval(pg_get_serial_sequence('public.doctors', 'id'), coalesce(max(id), 0) + 1, false) FROM public.doctors;
